"""Build the professional learning hub and three supporting portfolios."""
from pathlib import Path
from html import escape as e
R=Path(__file__).parent
BASE='https://iratt.github.io/MIT-AI-ML/'
COURSES=[
 dict(slug='bacnet',short='BACnet Basics',provider='The BACnet Institute',tag='Building automation',metric='6 lessons',headline='Make connected systems work together.',intro='A practical foundation for specifying, integrating and maintaining building automation systems across manufacturers.',status='Course completed',credential='Completion reported by Ian Alleyne. The reviewed folder contains study materials; a completion certificate was not present.',takeaways=[('Specify the interaction','Match the required data and command exchanges to complementary device capabilities.'),('Check capability and capacity','Use profiles, BIBBs, PICS and testing evidence alongside point counts and performance requirements.'),('Design for the lifecycle','Agree integration ownership, network responsibilities, engineering tools and support before procurement.')],cases=[('Cooling-plant integration checklist','Portfolio application','Define the values and commands exchanged between chillers, pumps, drives and the BMS. Record units, access rights, update methods and behavior when communication is unavailable.','A useful interface is one whose behavior and ownership are clear.'),('Read the capability evidence','Course example','The supplied drive PICS example distinguishes a writable frequency setpoint from read-only feedback. Use the required services and point permissions together when evaluating an interface.','A protocol label alone does not establish the required functionality.'),('Plan the communication workload','Study-guide calculation','For 100 controllers, one point each and a ten-second read interval, a request and response per point produces 1,200 application messages per minute before other traffic. Compare polling, grouped reads and change-of-value reporting.','Size for the actual workload and anticipated growth.')],modules=['Business case for BACnet','System integration','Networks and system functionality','Product descriptors: BIBBs, profiles and PICS','Conformance, capacity and testing evidence','Specification, ownership and support'],sources=['BACnet-Basics-Course-Summary.pdf — six-lesson study guide, prepared 22 October 2026','BACnet-Course-Source-PDFs.zip — source collection identified in the study guide'],note='The applications are portfolio synthesis from the supplied study guide. The guide explicitly distinguishes study review from completion evidence. No test score is claimed.'),
 dict(slug='schneider',short='Data Center Foundations',provider='Schneider Electric University',tag='Infrastructure & operations',metric='14 modules',headline='Understand the systems behind uptime.',intro='The Data Center Certified Associate Exam Learning Path connects availability, power, cooling, racks, cabling, security and infrastructure management to the business services they support.',status='Learning path completed',credential='Certificate awarded to Ian Alleyne for successful completion of the Data Center Certified Associate Exam Learning Path. The supplied certificate displays 10/12/2026.',takeaways=[('Think in dependencies','Review power, cooling, connectivity and operational processes as one service chain.'),('Design for usable capacity','Match rack density, airflow, distribution and redundancy to the load and its recovery needs.'),('Make monitoring actionable','Connect asset context, alarms and capacity information to operational decisions and sustainability metrics.')],cases=[('Availability and recovery','Learning synthesis','Distinguish equipment reliability from service availability. Define when an outage starts and when the business service is actually usable again, then examine both failure prevention and restoration.','Restoring utility power is only one step in restoring a service.'),('Cooling where the load needs it','Learning synthesis','Relate rack layout, inlet conditions, humidity and airflow separation to hot spots. Compare room, row and rack cooling in the context of density and physical constraints.','Aggregate cooling capacity does not guarantee suitable rack inlet conditions.'),('From infrastructure data to decisions','Study-reference application','Use an accurate asset inventory and dependency model to relate power, environment and access alarms to affected services. The supplied study reference integrates modern DCIM and distributed-site monitoring.','A useful dashboard links a signal to its operational consequence.')],modules=['Fundamentals of Availability','Examining Fire Protection Methods in the Data Center','Fundamentals of Cabling Strategies for Data Centers','Fundamentals of Cooling I','Fundamentals of Cooling II: Humidity','Fundamentals of Physical Security','Fundamentals of Power','Generator Fundamentals','Optimizing Cooling Layouts','Power Redundancy','Power Distribution I','Rack Fundamentals','Room, Row and Rack Based Cooling','Modern Data Center Physical Infrastructure Management'],sources=['Schneider-Electric-Data-Center-Study-Reference.docx — complete fourteen-module reference','DC Course Summaries.docx — illustrated course notes','Data Center Certified Associat Eam Certificate.pdf — completion certificate'],note='This portfolio summarizes the supplied study reference and notes. The certificate names the learning path; no separate exam score or professional designation is inferred. Practical examples are learning synthesis, not measured facility outcomes.'),
 dict(slug='cdcdp',short='Data Centre Design Professional',provider='CNet Training · An Uptime Education Company',tag='Design & engineering',metric='CDCDP®',headline='Turn requirements into an integrated design.',intro='Certified Data Centre Design Professional training brought together spatial planning, power, cooling, connectivity, life safety and commissioning through an applied data-center design case.',status='Certified · 16 November 2026',credential='Certified Data Centre Design Professional (CDCDP®), awarded to Ian Alleyne on 16 November 2026. Certification expiry: 31 December 2029.',takeaways=[('Translate business requirements','Develop cabinet and infrastructure arrangements around client needs, service boundaries and expansion.'),('Coordinate across disciplines','Reconcile cooling, power, cabling, access and life safety within the same physical space.'),('Revisit the design when demand changes','Use the revised client scenario to expose the consequences for layout and supporting infrastructure.')],cases=[('West Hall: a multi-client design','Final case study','The reviewed IA presentation organizes managed-hosting and colocation clients, rack configurations, cooling units, corridors, doors and expansion space. A revised slide responds to a client business update.','Spatial planning must leave room for both service delivery and change.'),('Trace the supporting paths','Final case study','Separate slides describe A and B power distribution components and pathways, A and B network cabling pathways, smoke detection, sprinkler coverage, cameras and access control.','Layered drawings help reveal interactions between infrastructure disciplines.'),('Connect layouts with calculations','Supporting coursework','The IA workbook records rack-unit positions, equipment power and weight. The folder also includes cable-containment calculations and earlier cabinet, power, cooling and cabling exercises.','A design narrative is stronger when its arrangements can be reconciled with its schedules.')],modules=['What is a Data Center','Compliance Review','The Data Center Structure','The Whitespace Floor','Communications Cabinets','Power Infrastructure','Electrical Safety','Cooling Infrastructure','Cable Pathways and Containment Systems','Data Center IT Connectivity','Designing for Fire Safety and Security','Project Commissioning and Closure'],sources=['Certified_Data_Center_Design_Professional_CDCDP__Certificate_2025.pdf — issued certificate; dates taken from its contents','CDCDP.FCS.Lorami DC2 West Hall V3.2 IA after business update.pptx — reviewed slide text','CDCDP.FCS.Lorami CoLo Power and Cabinet Layout V3.2 IA.xlsx — reviewed rack schedule','CDCDP.FCS.West Hall Project Specification Book V3.2.docx — educational client brief','Program Manuals-20261104 — twelve classroom module titles; three preparatory manual collections also retained'],note='Lorami is the educational case scenario. The design summary describes the reviewed coursework and does not certify compliance or claim a commissioned installation. Instructor templates and source materials retain their original attribution.')]

def head(title,desc,path):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | Ian Alleyne</title><meta name="description" content="{e(desc)}"><link rel="canonical" href="{BASE+path}"><meta property="og:title" content="{e(title)} | Ian Alleyne"><meta property="og:description" content="{e(desc)}"><meta property="og:url" content="{BASE+path}"><meta property="og:type" content="website"><meta name="twitter:card" content="summary"><link rel="icon" href="assets/favicon.svg"><link rel="stylesheet" href="assets/portfolio.css"></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="portfolio.html"><b class="mark">IA</b><span>Ian Alleyne<small>PROFESSIONAL LEARNING PORTFOLIO</small></span></a><nav aria-label="Main navigation"><a href="portfolio.html#courses">All courses</a><a href="https://github.com/IRATT/">GitHub ↗</a></nav></header>'''
def foot():
 return '<footer><span>Ian Alleyne, PhD, MBA · Independent learner portfolio</span><a href="portfolio.html">Explore all four portfolios →</a></footer><script src="assets/portfolio.js" defer></script></body></html>'
def share(path):
 return f'<div class="share"><span>Share this portfolio</span><button type="button" data-copy="{BASE+path}">Copy link</button><a href="https://www.linkedin.com/sharing/share-offsite/?url={BASE+path}" target="_blank" rel="noopener">Share on LinkedIn ↗</a><span role="status" aria-live="polite"></span></div>'
def build():
 cards=[('index.html','01','MIT xPRO','Advanced Analytics with AI, ML, and Data Science','6 months · 24 modules · 100%','Data in context. Decisions with value.','Predictive modeling, optimization, deep learning and responsible AI.')]+[(c['slug']+'.html',f'{i:02}',c['provider'],c['short'],c['metric']+' · Completed',c['headline'],c['intro']) for i,c in enumerate(COURSES,2)]
 body=head('Learning. Applied.','Four completed programs in AI, building automation and data-center infrastructure. Explore Ian Alleyne’s learning, credentials and applied work.','portfolio.html')
 body+='''<main id="main"><section class="hubhero"><span class="eyebrow">ENGINEERING · ANALYTICS · CRITICAL INFRASTRUCTURE</span><h1>Learning. <em>Applied.</em></h1><div class="herobottom"><p>Four completed programs. A connected perspective on intelligent systems, resilient infrastructure and decisions that create value.</p><a class="button" href="#courses">Explore the portfolios ↓</a></div><div class="ribbon"><span>Ian Alleyne, PhD, MBA</span><span>04 programs</span><span>2026 learning collection</span></div></section><section id="courses" class="section"><div class="sectionhead"><span class="eyebrow">CHOOSE A PORTFOLIO</span><h2>From insight to infrastructure.</h2><p>Explore the achievement, key takeaways and practical work behind each program.</p></div><div class="coursegrid">'''
 for path,num,provider,title,metric,headline,intro in cards:
  body+=f'<a class="coursecard card-{num}" href="{path}"><div class="cardtop"><span>{e(provider)}</span><b>{num}</b></div><h3>{e(title)}</h3><span class="pill">{e(metric)}</span><p>{e(intro)}</p><div class="cardlink">Explore portfolio <span>↗</span></div></a>'
 body+='''</div></section><section class="connection"><span class="eyebrow">ONE CONNECTED PRACTICE</span><h2>Understand the data.<br>Connect the systems.<br>Design for the service.</h2><p>These programs bring analytical methods together with building controls, infrastructure fundamentals and integrated data-center design. Each portfolio shows how the learning informs my engineering judgment.</p></section>'''+share('portfolio.html')+'</main>'+foot()
 (R/'portfolio.html').write_text(body)
 for c in COURSES:
  path=c['slug']+'.html';out=head(c['short'],c['intro'],path)
  out+=f'<main id="main"><section class="coursehero"><a class="back" href="portfolio.html">← All portfolios</a><span class="eyebrow">{e(c["provider"])}</span><div class="herogrid"><div><h1>{e(c["short"])}</h1><p class="lede">{e(c["headline"])}</p><p>{e(c["intro"])}</p><a class="button" href="#work">Explore the learning ↓</a></div><aside class="achievement"><span>{e(c["status"])}</span><strong>{e(c["metric"])}</strong><p>{e(c["credential"])}</p>'
  if c.get('pdf'):out+=f'<a href="assets/{c["pdf"]}" target="_blank" rel="noopener">View completion certificate ↗</a>'
  out+='</aside></div></section><section class="section" id="work"><div class="sectionhead"><span class="eyebrow">KEY TAKEAWAYS</span><h2>What the learning makes possible.</h2></div><div class="takeaways">'
  for i,(title,txt) in enumerate(c['takeaways'],1):out+=f'<article><span class="number">0{i}</span><h3>{e(title)}</h3><p>{e(txt)}</p></article>'
  out+='</div></section><section class="section work"><div class="sectionhead"><span class="eyebrow">APPLIED LEARNING</span><h2>From concepts to practical choices.</h2></div>'
  for title,label,txt,insight in c['cases']:out+=f'<article class="case"><div><span class="eyebrow">{e(label)}</span><h3>{e(title)}</h3></div><div><p>{e(txt)}</p><p class="insight">{e(insight)}</p></div></article>'
  out+='</section><section class="section records"><details><summary><span>Course record<small>'+str(len(c['modules']))+' topics · expand to explore</small></span><span aria-hidden="true">＋</span></summary><ol class="modulelist">'+''.join('<li>'+e(x)+'</li>' for x in c['modules'])+'</ol></details><details><summary><span>Sources &amp; evidence<small>Materials behind this portfolio</small></span><span aria-hidden="true">＋</span></summary><div class="sourcebody"><ul>'+''.join('<li>'+e(x)+'</li>' for x in c['sources'])+'</ul><p>'+e(c['note'])+'</p><p>Summaries are independently prepared from Ian’s training folder. AI assistance was used to organize and edit the portfolio. Full course manuals and private administrative documents are not reproduced.</p></div></details></section>'+share(path)+'</main>'+foot()
  (R/path).write_text(out)
if __name__=='__main__':build()
